practice.solution:
const gradebook = { ada: [90, 85], linus: [70] };

const shallow = Object.assign({}, gradebook);
shallow.ada.push(100);

const deep = structuredClone(gradebook);
deep.linus.push(60);

console.log(`ada: ${gradebook.ada.length}`);
console.log(`linus: ${gradebook.linus.length}`);
console.log(`assign shares ada: ${shallow.ada === gradebook.ada}`);
console.log(`clone shares linus: ${deep.linus === gradebook.linus}`);

const meta = { owner: "kim", seen: new Set(["ada"]), term: undefined };
const jsonCopy = JSON.parse(JSON.stringify(meta));
const cloned = structuredClone(meta);
console.log(`json: ${JSON.stringify(jsonCopy)}, has term: ${"term" in jsonCopy}`);
console.log(`clone seen ada: ${cloned.seen.has("ada")}, has term: ${"term" in cloned}`);
